class Solution { public:string findTheString(vector<vector<int>>& lcp){int n=lcp.size();string answer(n,0);char next='a';for(int i=0;i<n;++i){if(answer[i])continue;if(next>'z')return "";for(int j=i;j<n;++j)if(lcp[i][j]>0)answer[j]=next;++next;}vector<vector<int>> actual(n+1,vector<int>(n+1));for(int i=n-1;i>=0;--i)for(int j=n-1;j>=0;--j){if(answer[i]==answer[j])actual[i][j]=actual[i+1][j+1]+1;if(actual[i][j]!=lcp[i][j])return "";}return answer;} };
